    ++votes[StageModel_Tree51(features)];
    ++votes[StageModel_Tree52(features)];
    ++votes[StageModel_Tree53(features)];
    ++votes[StageModel_Tree54(features)];
    ++votes[StageModel_Tree55(features)];
    uint8_t best_class = 0U;
    uint8_t best_votes = votes[0];
    for (uint8_t i = 1U; i < STAGE_MODEL_CLASS_COUNT; ++i)
    {
        if (votes[i] > best_votes)
        {
            best_class = i;
            best_votes = votes[i];
        }
    }
    static const uint8_t labels[STAGE_MODEL_CLASS_COUNT] = {
        0U, 1U, 2U, 3U, 4U, 5U, 6U, 9U
    };
    return labels[best_class];
